p='/app/benchmark/source_data.json'
d=json.load(open(p))
nodes={r['node_id']:r for r in d['architecture_nodes']['data']}
edges=d['architecture_edges']['data']
print('CONSUMPTION NODES')
for r in d['architecture_nodes']['data']:
 if r['layer']=='consumption': print(r)
print('EDGES FULL')
for e in edges: print(e)
# agg source category -> ingestion
agg=defaultdict(float)
for e in edges:
 if nodes[e['source']]['layer']=='source' and nodes[e['target']]['layer']=='ingestion':
  agg[(nodes[e['source']]['category'], nodes[e['target']]['label'])]+=e['volume_gb'] or 0
print('cat->ing')
for k,v in agg.items(): print(k,v)
# layer to layer sums
for a,b in [('ingestion','bronze'),('bronze','silver'),('silver','gold')]:
 s=defaultdict(float)
 for e in edges:
  if nodes[e['source']]['layer']==a and nodes[e['target']]['layer']==b:
   s[(nodes[e['source']]['label'], nodes[e['target']]['label'])]+=e['volume_gb'] or 0
 print(a,b,sum(s.values()),len(s))
 for k,v in s.items(): print(k,v)
# gold to consumption fanout counts
fan=defaultdict(int); types=defaultdict(int)
for e in edges:
 if nodes[e['source']]['layer']=='gold' and nodes[e['target']]['layer']=='consumption':
  fan[nodes[e['source']]['label']]+=1
  types[nodes[e['target']]['category']]+=1
print('fan',fan,'types',types)
print('source category totals')
cat=defaultdict(float)
for r in nodes.values():
 if r['layer']=='source': cat[r['category']]+=r['daily_volume_gb'] or 0
print(dict(cat))
print('layer totals nodes')
for layer in ['source','ingestion','bronze','silver','gold']:
 print(layer, sum((r['daily_volume_gb'] or 0) for r in nodes.values() if r['layer']==layer))
print('gov counts')
gov=defaultdict(int)
for r in d['governance_controls']['data']: gov[r['layer']]+=1
print(dict(gov))
trans=defaultdict(int)
for r in d['transformation_summary']['data']: trans[r['layer']]+=r['count']
print('trans',dict(trans))
